sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // MSSCOLATRL-185

	// var collateral_task=current.sys_id;
	// gs.info("Testing Collateral Task" +collateral_task);

	// var settmoves=new x_hsb11_mss_coll_0.MSS_Collateral_Utils().setSettmovesFlag(collateral_task);

	var collateral_case = current.collateral_case_id;
	var colCase = new GlideRecord('x_hsb11_mss_coll_0_collateral_case_table');
	colCase.get(collateral_case);
	colCase.query();

	if(colCase.next()){
		colCase.state = 3; //completed;
		colCase.update();
	}
	//gs.info("Complete Treats Case Record executed");

})(current, previous);
